with q as (select * from (values
('pcac-lc303-delegate-degree-45','LC nº 303/2015 — ingresso de Delegado','O cargo de Delegado de Polícia Civil é privativo de:','(A) qualquer curso superior.\n(B) bacharel em Direito.\n(C) tecnólogo em Segurança Pública.\n(D) curso técnico em investigação.\n(E) ensino médio completo.','B','O art. 2º da LC nº 303/2015 determina que o cargo é privativo de bacharel em Direito.'),
('pcac-lc303-delegate-classes-46','LC nº 303/2015 — estrutura da carreira','A carreira de Delegado de Polícia Civil é estruturada em:','(A) três classes.\n(B) quatro classes.\n(C) cinco classes, de I a V, sendo a última Especial.\n(D) cinco referências dentro de uma classe única.\n(E) seis classes.','C','O art. 4º, § 1º, prevê cinco classes: I, II, III, IV e Especial.'),
('pcac-lc303-no-progression-47','LC nº 303/2015 — progressão','Na carreira de Delegado, conforme o art. 4º, § 2º, da LC nº 303/2015:','(A) existe progressão a cada 36 meses entre referências.\n(B) foi extinta a progressão e o correspondente sistema de referências salariais.\n(C) há duas progressões por classe.\n(D) a promoção foi extinta.\n(E) o desenvolvimento ocorre apenas por antiguidade automática.','B','A LC nº 303/2015 extinguiu para Delegado a progressão e o sistema de referências salariais; o desenvolvimento se dá por promoção entre classes.'),
('pcac-lc303-extra-duty-48','LC nº 303/2015 — sujeição a serviço','O adicional de sujeição a serviço e convocação extraordinária incluído pela LC nº 401/2022 corresponde a:','(A) 3% dos vencimentos.\n(B) 5% dos vencimentos.\n(C) 7% dos vencimentos, de caráter indenizatório, relacionado ao sobreaviso permanente fora da jornada ordinária.\n(D) 10% da remuneração, incorporável.\n(E) 15% do subsídio.','C','O art. 6º-A, incluído pela LC nº 401/2022, prevê adicional indenizatório de 7% dos vencimentos para o regime de sobreaviso permanente fora da jornada ordinária, conforme redação consolidada e ressalvas legais.')
) as t(external_item_key,subtopic,question_text,options_text,answer,explanation))
